from pptx import Presentation
from pptx.util import Inches,Pt
from pptx.dml.color import RGBColor
from pptx.enum.shapes import MSO_SHAPE
p=Presentation();p.slide_width=Inches(13.33);p.slide_height=Inches(7.5)
N=RGBColor(23,50,77);B=RGBColor(47,107,138);G=RGBColor(83,97,107);L=RGBColor(238,244,247)
def slide(t):
 s=p.slides.add_slide(p.slide_layouts[6]);q=s.shapes.add_shape(MSO_SHAPE.RECTANGLE,0,0,p.slide_width,Inches(.16));q.fill.solid();q.fill.fore_color.rgb=B;q.line.fill.background();x=s.shapes.add_textbox(Inches(.55),Inches(.35),Inches(12),Inches(.5));x.text=t;x.text_frame.paragraphs[0].font.size=Pt(24);x.text_frame.paragraphs[0].font.bold=True;x.text_frame.paragraphs[0].font.color.rgb=N;return s
def tx(s,x,y,w,h,t,sz=16,b=False,c=N,fill=None):
 z=s.shapes.add_textbox(Inches(x),Inches(y),Inches(w),Inches(h));
 if fill:z.fill.solid();z.fill.fore_color.rgb=fill;z.line.color.rgb=fill
 z.text_frame.word_wrap=True;z.text_frame.margin_left=Inches(.08);z.text_frame.margin_right=Inches(.08);z.text=t
 for p0 in z.text_frame.paragraphs:p0.font.size=Pt(sz);p0.font.bold=b;p0.font.color.rgb=c
 return z
def tb(s,rows,y,h,fs=12):
 sh=s.shapes.add_table(len(rows),len(rows[0]),Inches(.6),Inches(y),Inches(12.1),Inches(h));t=sh.table
 for j in range(len(rows[0])):t.columns[j].width=Inches(12.1/len(rows[0]))
 for i,r in enumerate(rows):
  for j,v in enumerate(r):
   c=t.cell(i,j);c.text=str(v);c.fill.solid();c.fill.fore_color.rgb=B if i==0 else (L if i%2 else RGBColor(255,255,255));c.margin_left=Inches(.05);c.margin_right=Inches(.05)
   for p0 in c.text_frame.paragraphs:p0.font.size=Pt(fs);p0.font.color.rgb=RGBColor(255,255,255) if i==0 else N;p0.font.bold=i==0
# slides content
s=slide('1｜本周工作总览：把跨模型迁移方案推进到可验证阶段');tx(s,.7,1.0,12,.8,'本周围绕“细胞系药敏信息能否帮助类器官单药筛选”完成研究方案、数据准入、模型训练、迁移实验和外部验证准备。',18,c=G);tb(s,[['工作包','本周完成','形成结果'],['方案','明确研究问题、假设、指标和停止标准','形成可执行研究合同'],['数据','完成来源/目标表达、药物和样本身份核验','确定可用队列及数据限制'],['算法','完成来源模型、PDO模型和迁移模型比较','获得首轮性能结果'],['验证','完成PRISM严格未见细胞身份审计','具备跨研究测试条件']],2.05,3.25)
s=slide('2｜研究背景：为什么需要细胞系到类器官迁移');tx(s,.7,1.0,12,1.0,'细胞系数据量大但属于二维培养体系；PDO更接近患者肿瘤状态，却存在样本量小、药物面板窄和表达—药敏配对不足的问题。项目目标是用来源域数据降低PDO建模的数据需求。',18,c=G);tb(s,[['对象','优势','限制'],['细胞系','样本多、药敏药物覆盖广，适合预训练','与三维类器官存在培养体系和状态差异'],['PDO/PDxO','更接近患者肿瘤生物学','样本少、药物交集小、难以单独训练复杂模型'],['计算模型','可整合表达和药物结构','必须证明迁移增益，不能直接外推临床疗效']],2.35,2.5)
s=slide('3｜本周新增数据与三篇Nature论文');tx(s,.7,1.0,12,.9,'本周将三篇Nature研究从文献背景转化为项目数据接口：分别支持三维模型域差异分析、功能辅助训练和解释验证。',18,c=G);tb(s,[['论文/数据','数据内容','进入项目的实验环节'],['NextGen DepMap','三维模型表达、培养类型、基因依赖','三维表达适配、二维/三维域差异分析'],['HCMI配对模型','肿瘤与来源模型的配对表达和保持度','学习可迁移特征，分析培养体系差异'],['类器官功能生物库','类器官表达和CRISPR依赖','功能辅助训练、靶点解释和独立一致性检查'],['数据边界','功能依赖不是药敏真值；论文样本量不能直接相加','只作为辅助监督或外部支持']],2.15,3.25)
s=slide('4｜研究方案：从来源学习到PDO排序');tx(s,.7,1.0,12,.85,'方案采用“来源预训练—目标适配—功能辅助—外部验证”的递进路线，每一步都与简单基线比较，避免复杂模型掩盖数据不足。',18,c=G);tb(s,[['阶段','输入','主要方法','判断标准'],['来源学习','细胞系表达+单药药敏+药物结构','表达编码器、分子结构编码器、双编码器','是否超过药物平均效应'],['PDO适配','PDO表达+共同药物药敏','PDO从头模型、直接迁移、低自由度适配','是否超过简单基线'],['功能辅助','三维表达+依赖标签','掩码重建、依赖多任务监督','是否改善PDO药物排序'],['外部验证','PRISM严格未见细胞','冻结模型、表达置换、细胞块bootstrap','是否跨研究复现']],2.05,3.55,11)
s=slide('5｜数据处理与质量控制：本周完成的具体工作');tx(s,.7,1.0,12,.85,'本周重点不是直接训练网络，而是先保证不同研究中的样本、药物和表达可以被公平比较。',18,c=G);tb(s,[['处理对象','本周处理','结果/限制'],['样本身份','统一细胞系、PDO、患者和模型ID；排除外部测试身份重叠','PRISM 877个细胞中排除523个GDSC重叠细胞'],['药物身份','以完整InChIKey进行严格匹配，保留盐型和实体差异','Zhu严格共享7种药物；PRISM匹配104种'],['表达矩阵','固定公共基因空间，记录TPM/FPKM及缩放方式','识别来源与目标表达尺度差异'],['数据划分','患者/细胞整组留出，预处理只在训练折拟合','避免同患者或同细胞泄漏'],['外部数据','PRISM标签不参与训练、选模或阈值制定','获得354个严格未见细胞']],2.05,3.6,11)
s=slide('6｜算法与实验设计：比较什么，为什么比较');tx(s,.7,1.0,12,.85,'算法比较围绕“药物普遍效应、目标域表达信号、来源域迁移信号”逐层展开，而不是直接从复杂网络开始。',18,c=G);tb(s,[['模型层级','算法内容','回答的问题'],['简单基线','按训练数据估计药物平均敏感性','药物本身是否已解释大部分排序'],['PDO自身模型','正则化表达模型','目标域是否存在稳定个体化信号'],['直接迁移','冻结细胞系表达+药物模型','来源规律能否零样本迁移'],['受控适配','冻结编码器、全量微调、来源参数收缩','低自由度调整能否减少负迁移'],['功能辅助','表达重建、依赖监督、标签置换','功能数据是否提供独立增量']],2.05,3.65,11)
s=slide('7｜实验结果：来源域有表达信号，PDO迁移尚未成立');tx(s,.7,1.0,12,.85,'本周结果形成了清晰的分层结论：来源域模型有小幅表达增益，但在当前PDO队列上没有转化为更好的药物排序。',18,c=G);tb(s,[['实验','数据规模/设置','结果','结论'],['来源cold-cell','细胞系整组留出；3个初始化','NDCG@5约0.956→0.963；表达置换后下降','来源域存在有限表达信号'],['Zhu PDO','20个PDO；7种共同药物；患者留出','简单基线约0.748；迁移模型约0.61–0.65','出现负迁移'],['功能辅助','三维表达/依赖监督；关闭和置换对照','有轻微方向性变化，但低于简单基线','暂不能证明功能数据改善筛药'],['PRISM准备','354个严格未见细胞；104种共同药物','正式测试待完成','用于判断跨研究复现']],1.95,4.0,10)
s=slide('8｜阶段结论：当前瓶颈是数据条件，不是网络复杂度');tx(s,.7,1.0,12,1.0,'本周已经完成从“提出迁移假设”到“验证迁移边界”的推进。当前证据支持来源域表达信号，但不支持把细胞系模型直接称为有效PDO迁移模型。',18,c=G);tb(s,[['已确认','尚未确认','对应决策'],['来源模型可训练且可重复','表达信号能否迁移到PDO','完成PRISM和第二PDO队列验证'],['功能数据可接入辅助训练','是否能提升最终药物排序','暂不扩展复杂功能网络'],['PDO结果受数据限制明显','模型是否在更大队列有效','优先扩大样本和共同药物'],['项目可形成研究结论','当前不能声称临床预测','定位为研究级候选筛选']],2.25,3.2)
s=slide('9｜下周计划、交付物与所需支持');tx(s,.7,1.0,12,.85,'下周重点从“继续增加模型”转向“完成独立验证、补足数据条件并形成可汇报的阶段结论”。',18,c=G);tb(s,[['计划','具体工作','交付物/所需支持'],['PRISM正式评测','冻结模型，完成原始/置换表达和细胞级bootstrap','跨研究泛化结果表；维持算力和数据版本'],['第二PDO队列','筛选具备表达+单药响应配对的数据集','独立队列候选清单；需要数据来源协助'],['基线模型固化','比较药物平均、正则化表达和低自由度校准','可解释的PDO候选药物排序流程'],['阶段决策','根据外部结果决定是否继续通路和功能网络','需要确认下一阶段资源优先级']],2.05,3.65,11)
p.save('本周工作汇报_类器官单药筛选迁移_完整详版.pptx')
